<template><div class="page"><header><div><p class="eyebrow">AI 纠察中心</p><h1>SmartOps Inspector</h1><p>监督 AI 自己：行为、证据、工具、风险、审批与验证</p></div><RouterLink class="link" to="/inspector/desk?view=events">在洞察台打开</RouterLink><RouterLink class="link" to="/inspector/statistics">查看统计</RouterLink></header><el-alert v-if="error" :title="error" type="error" show-icon @close="error=''"/><InspectorSummary :summary="summary"/><section class="dimensions"><span v-for="item in dimensions" :key="item">{{ item }}</span></section><section class="panel"><div class="panel-title"><h2>Inspection Timeline</h2><button @click="load">刷新</button></div><InspectorTimeline :events="events" @select="openEvent"/></section></div></template>
<script setup>
import{onMounted,ref}from'vue';import{useRouter}from'vue-router';import{getInspectorEvents,getInspectorSummary}from'../../api/inspector';import InspectorSummary from'../../components/inspector/InspectorSummary.vue';import InspectorTimeline from'../../components/inspector/InspectorTimeline.vue';
const router=useRouter(),summary=ref({}),events=ref([]),error=ref('');const dimensions=['Agent Behavior','Evidence Quality','Tool Usage','Risk','Approval','Verification','Knowledge','Security'];
async function load(){error.value='';try{const[s,e]=await Promise.all([getInspectorSummary(),getInspectorEvents()]);summary.value=s.data||{};events.value=e.data||[]}catch(err){error.value=err.message||'Inspector 服务不可用'}}function openEvent(event){router.push(`/inspector/events/${event.id}`)}onMounted(load)
</script>
<style scoped>.page{display:grid;gap:20px}header,.panel-title{display:flex;justify-content:space-between;align-items:flex-start}h1{margin:0;font-size:30px}header p{color:var(--smart-muted)}.eyebrow{color:#e7c56d;font-weight:700;margin:0 0 6px}.link,button{padding:9px 14px;border:1px solid rgba(225,183,73,.3);background:#241e0e;color:#f1d98c;border-radius:7px;cursor:pointer}.link:hover,button:hover{border-color:#e7c56d;background:#332912}.dimensions{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.dimensions span{padding:14px;background:linear-gradient(145deg,#302610,#1e180b);color:#ead28b;border:1px solid rgba(225,183,73,.24);border-radius:8px;box-shadow:inset 0 1px 0 rgba(255,230,145,.05)}.panel{padding:20px;background:linear-gradient(145deg,#2a220f,#1b1509);border:1px solid rgba(225,183,73,.3);border-radius:9px;box-shadow:0 14px 32px rgba(50,32,0,.2)}.panel-title{align-items:center;margin-bottom:14px}.panel h2{margin:0;color:#f2db98}@media(max-width:800px){.dimensions{grid-template-columns:repeat(2,1fr)}}</style>
